frappe.ui.form.on("Advisory And Recommendations", {
    refresh(frm) {
        // Do not show the button for a new/unsaved document
        if (frm.is_new()) {
            return;
        }

        // Client Information must be linked
        if (!frm.doc.identifier) {
            return;
        }

        frm.add_custom_button(__("PRINT REPORT"), function () {
            const print_format = "Financial Assessment Report";

            const url =
                "/printview" +
                "?doctype=" + encodeURIComponent("Client Information") +
                "&name=" + encodeURIComponent(frm.doc.identifier) +
                "&format=" + encodeURIComponent(print_format) +
                // &trigger_print=1  <-- removed to show preview first
                 "&no_letterhead=0";

            window.open(url, "_blank");
        }).addClass("btn-primary");
    }
});
